export function generateEmail(nom, slug = 'usine') {
    if (!nom || nom.trim() === '') return '';
    const mots = nom.trim().split(/\s+/);
    if (mots.length < 2) return '';

    const prenom     = mots[0];
    const nomFamille = mots.slice(1).join('');
    
    const clean = (str) => str
        .toLowerCase()
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '');

    return `${clean(prenom).charAt(0)}.${clean(nomFamille)}@${slug}.local`;
}
